import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { writeFile } from "./build.utils";

const buildDir = path.dirname(fileURLToPath(import.meta.url));
const rootDir = path.resolve(buildDir, "..");
const langDir = path.join(rootDir, "lang");

const cjsBanner = (setName: string): string => `/**
 * DO NOT EDIT THIS FILE. It is automatically generated
 * from its .mjs counterpart (same filename but with .mjs extension).
 * Edit that file instead (${setName}).
 */
`;

function parse(prop: string, txt: string): string {
  const propIndex = txt.indexOf(prop);
  const startIndex = txt.indexOf("'", propIndex) + 1;
  let stopIndex = txt.indexOf("'", startIndex);

  while (txt.charAt(stopIndex - 1) === "\\") {
    stopIndex = txt.indexOf("'", stopIndex + 1);
  }

  return txt.substring(startIndex, stopIndex).replace("\\", "");
}

function convertToCjs(content: string, banner = ""): string {
  return banner + content.replace(/export default\s+/, "module.exports = ");
}

export async function buildLang(): Promise<void> {
  const languages: Array<{ isoName: string; nativeName: string }> = [];
  const files = fs
    .readdirSync(langDir)
    .filter((file) => file.endsWith(".mjs"))
    .sort((a, b) => a.localeCompare(b));

  await Promise.all(
    files.map((file) => {
      const fullPath = path.join(langDir, file);
      const content = fs.readFileSync(fullPath, "utf-8");
      const isoName = parse("isoName", content);
      const nativeName = parse("nativeName", content);

      languages.push({ isoName, nativeName });

      return writeFile(
        fullPath.replace(/\.mjs$/, ".js"),
        convertToCjs(content, cjsBanner(path.basename(file))),
      );
    }),
  );

  languages.sort((a, b) => a.isoName.localeCompare(b.isoName));

  await writeFile(path.join(langDir, "index.json"), JSON.stringify(languages, null, 2) + "\n");
}

if (import.meta.url === `file://${process.argv[1]}`) {
  buildLang().catch((err: unknown) => {
    console.error(err);
    process.exit(1);
  });
}
